"""Validated extraction and ordered human-review routing."""
from datetime import date
from pathlib import Path
import re

from .core import SCALARS, strict_json, validate_extraction

REQUIRED = tuple(key for key in SCALARS if key != 'kind')


def route(value):
    issues = value['issues']
    if any(issue.lower().startswith('override:') for issue in issues):
        return 'review', 'IT Service Desk', 'inspect-message'
    if value['kind'] == 'withdrawal' and value['request_id'] and value['request_date']:
        return 'review', 'IT Service Desk', 'confirm-withdrawal'
    if (value['kind'] not in ('new', 'change')
            or any(value[key] is None for key in REQUIRED)
            or any(issue.lower().startswith(('conflict:', 'mismatch:', 'date-order:')) for issue in issues)
            or (value['start_date'] and value['end_date'] and value['start_date'] > value['end_date'])):
        return 'needs-information', 'IT Service Desk', 'clarify'
    if value['environment'] == 'production' or value['permission'] in ('write', 'admin'):
        return 'review', 'Security Review', 'review-risk-then-owner'
    return 'review', 'System Owner', 'review-request'


def decode_reply(reply, source):
    raw = reply.raw_response
    if not isinstance(raw, dict) or not isinstance(raw.get('choices'), list) or len(raw['choices']) != 1:
        raise ValueError('Provider response must contain exactly one choice')
    choice = raw['choices'][0]
    message = choice.get('message', {})
    if message.get('refusal'):
        raise ValueError('Provider refused extraction')
    if choice.get('finish_reason') != 'stop':
        raise ValueError('Provider response is interrupted or has unsupported completion status')
    content = message.get('content')
    if not isinstance(content, str):
        raise ValueError('Provider returned no text extraction')
    value = strict_json(content)
    validate_extraction(value, source.message)
    for field in SCALARS:
        item = value[field]
        if isinstance(item, str) and not item.strip():
            raise ValueError(f'Empty {field}: use null and an explanatory issue')
        if item is None and not any(field in issue for issue in value['issues']):
            value['issues'].append(f'missing:{field}: absent or unresolved in message')
    for field in ('request_date', 'start_date', 'end_date'):
        item = value[field]
        if item is not None:
            if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', item):
                raise ValueError(f'{field} must use YYYY-MM-DD')
            date.fromisoformat(item)
    if value['request_id'] and value['request_id'] != Path(source.document_id).stem:
        issue = f'mismatch:request_id: {value["request_id"]} differs from {source.document_id}'
        if issue not in value['issues']:
            value['issues'].append(issue)
    if value['start_date'] and value['end_date'] and value['start_date'] > value['end_date']:
        if not any(issue.startswith('date-order:') for issue in value['issues']):
            value['issues'].append('date-order:start_date after end_date')
    marker = re.search(r'SYSTEM\s+OVERRIDE\s*:', source.message, re.IGNORECASE)
    if marker:
        evidence = source.message[marker.start():]
        if not any(issue.lower().startswith('override:') for issue in value['issues']):
            value['issues'].append('override:' + evidence)
        if evidence not in value['supporting_quotes']:
            value['supporting_quotes'].append(evidence)
    return value


def extract(source, provider):
    reply = provider.complete(message=source.message, fixture_name=source.document_id.lower())
    value = decode_reply(reply, source)
    status, owner, action = route(value)
    return {'document_id':source.document_id, 'source_sha256':source.source_sha256,
            'extraction':value, 'status':status, 'owner':owner, 'next_action':action,
            'error':None, 'response_source':reply.response_source, 'export_metadata':source.metadata}

"""Bounded scheduling, renewable claims and persisted retry attempts."""
from concurrent.futures import ThreadPoolExecutor, wait, FIRST_COMPLETED
import threading
import time

from .config import make_provider


def _work(store, job, token, factory):
    stopped = threading.Event()
    def heartbeat():
        while not stopped.wait(20):
            if not store.renew(job,token):
                return
    thread = threading.Thread(target=heartbeat,daemon=True)
    thread.start()
    try:
        attempt = store.get(job)
        try:
            record = store.execute(job,factory(attempt['settings']))
        except Exception as error:
            record = {'document_id':attempt['document_id'],'source_sha256':attempt['source_sha256'],
                      'extraction':None,'status':'error','owner':'IT Service Desk',
                      'next_action':'retry-extraction','error':'Input or configuration error: '+type(error).__name__,
                      'response_source':('mock' if attempt['settings']['provider']=='mock' else 'openai:'+attempt['settings']['model'])}
        published = store.finish(job,token,record)
        return job,record,published
    finally:
        stopped.set()
        thread.join()


def run_pending(store, *, job_ids=None, workers=4, rate_per_minute=60,
                max_attempts=3, retry_delay=1, provider_factory=None):
    if workers < 1 or max_attempts < 1 or rate_per_minute < 0 or retry_delay < 0:
        raise ValueError('Workers/attempts must be positive; rate and retry delay nonnegative')
    factory = provider_factory or make_provider
    selected = set(job_ids) if job_ids is not None else None
    running = {}
    counts = {}
    completed = 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        while True:
            pending = [item for item in store.pending() if selected is None or item['id'] in selected]
            for item in pending:
                if len(running) >= workers:
                    break
                if item['id'] in running.values():
                    continue
                token = store.claim(item['id'],max_inflight=workers,rate_per_minute=rate_per_minute)
                if token:
                    future = pool.submit(_work,store,item['id'],token,factory)
                    running[future] = item['id']
            if not pending and not running:
                break
            if not running:
                time.sleep(.05)
                continue
            done,_ = wait(running,timeout=.05,return_when=FIRST_COMPLETED)
            for future in done:
                job,record,finished = future.result()
                del running[future]
                completed += int(finished)
                count = counts.get(job,1)
                if finished and record.get('retryable') and count < max_attempts:
                    # Do not retry an obsolete generation over a newer source.
                    if any(row['attempt_id']==job and 'newer_pending_attempt' not in row for row in store.current()):
                        new = store.retry(job,delay=min(30,retry_delay*2**(count-1)))
                        counts[new] = count+1
                        if selected is not None:
                            selected.add(new)
    return {'completed_attempts':completed,'pending':len(store.pending()),
            'current_documents':len(store.current())}

"""Operator commands; all intake defaults to reproducible mock responses."""
import argparse
import json
from pathlib import Path
import sys

from .config import settings
from .core import Source, decode_source, sha256
from .state import Store
from .worker import run_pending


def parser():
    result = argparse.ArgumentParser(description='Prepare an access-request queue for human review')
    commands = result.add_subparsers(dest='command',required=True)
    for name in ('intake','queue','pending','history','retry','resume'):
        command = commands.add_parser(name)
        command.add_argument('--state',default='.state/intake.db')
        if name in ('intake','retry','resume'):
            command.add_argument('--workers',type=int,default=4)
            command.add_argument('--rate-per-minute',type=int,default=None)
            command.add_argument('--max-attempts',type=int,default=3)
        if name == 'intake':
            command.add_argument('--input',action='append',required=True)
            command.add_argument('--provider',choices=['mock','openai'],default='mock')
            command.add_argument('--model')
            command.add_argument('--base-url',default='https://api.openai.com/v1')
            command.add_argument('--fixtures',default='tests/mock_responses')
            command.add_argument('--timeout',type=float,default=60)
            command.add_argument('--max-completion-tokens',type=int,default=4096)
            command.add_argument('--force',action='store_true')
            command.add_argument('--enqueue-only',action='store_true')
        if name == 'history':
            command.add_argument('--document',required=True)
        if name == 'retry':
            command.add_argument('--attempt',type=int,required=True)
    return result


def discover(inputs):
    sources = {}
    for name in inputs:
        path = Path(name)
        paths = sorted(path.glob('*.json')) if path.is_dir() else [path]
        if not paths:
            raise ValueError('Input directory contains no JSON exports')
        for item in paths:
            raw = item.read_bytes()
            if item.name in sources:
                raise ValueError('Duplicate input filename in this batch: '+item.name)
            try:
                source = decode_source(item.name,raw)
            except (UnicodeError, ValueError):
                # Retain malformed input bytes as a failed document, rather than
                # stopping unaffected documents. The worker exposes its error.
                source = Source(item.name,raw,sha256(raw),'',{})
            sources[item.name] = source
    return list(sources.values())


def dispatch(args):
    store = Store(args.state)
    if args.command == 'queue':
        return store.current()
    if args.command == 'pending':
        return store.pending()
    if args.command == 'history':
        return [{key:value for key,value in row.items() if key != 'raw'} for row in store.history(args.document)]
    selected = None
    if args.command == 'intake':
        if args.provider == 'openai' and not args.model:
            raise ValueError('Provider mode requires an explicit --model')
        if args.timeout <= 0 or args.max_completion_tokens <= 0:
            raise ValueError('Timeout and completion-token budget must be positive')
        config = settings({'provider':args.provider,'model':args.model or 'mock',
                           'base_url':args.base_url,'fixture_dir':args.fixtures,
                           'timeout':args.timeout,'max_completion_tokens':args.max_completion_tokens})
        sources = discover(args.input)
        selected = [store.register(source,config,force=args.force) for source in sources]
        if args.enqueue_only:
            return {'registered_documents':len(selected),'pending':len(store.pending())}
    elif args.command == 'retry':
        selected = [store.retry(args.attempt)]
    rate = args.rate_per_minute
    if rate is None:
        # A resumed database may include live jobs: default conservatively.
        rate = 0 if args.command == 'intake' and args.provider == 'mock' else 60
    return run_pending(store,job_ids=selected,workers=args.workers,
                       rate_per_minute=rate,max_attempts=args.max_attempts)


def main(argv=None):
    args = parser().parse_args(argv)
    try:
        output = dispatch(args)
    except (OSError, ValueError) as error:
        # Never print a traceback with provider request state/credentials.
        print(json.dumps({'error':str(error)}),file=sys.stderr)
        return 2
    print(json.dumps(output,ensure_ascii=False,indent=2))
    return 0

"""Source-owned expected facts and an explicit fixed-denominator comparison."""
import json
from pathlib import Path

from .core import SCALARS, validate_extraction


def compare(records, expected):
    actual = {}
    for record in records:
        if record['document_id'] in actual:
            raise ValueError('Duplicate current record in accuracy input')
        actual[record['document_id']] = record
    result = {'matched':0,'total':len(expected)*len(SCALARS),'routing_matches':0,
              'documents':len(expected),'differences':[],'quote_errors':[],
              'issue_errors':[],'schema_errors':[],
              'unexpected_documents':sorted(set(actual)-set(expected))}
    for name,oracle in expected.items():
        record = actual.get(name,{})
        value = record.get('extraction') if record.get('status') != 'error' else None
        for field in SCALARS:
            if value is not None and field in value and value[field] == oracle['facts'][field]:
                result['matched'] += 1
            else:
                result['differences'].append({'document_id':name,'field':field,
                    'expected':oracle['facts'][field],
                    'actual':value.get(field) if isinstance(value,dict) else '<missing/error extraction>'})
        if all(record.get(field)==value for field,value in oracle['route'].items()):
            result['routing_matches'] += 1
        if value is None:
            result['schema_errors'].append(name+': no valid extraction')
            continue
        try:
            validate_extraction(value)
        except ValueError:
            result['schema_errors'].append(name+': schema invalid')
        if not value.get('supporting_quotes') or any(quote not in oracle['source_quote'] for quote in value.get('supporting_quotes',[])):
            result['quote_errors'].append(name)
        for field,expected_value in oracle['facts'].items():
            if expected_value is None and not any(field in issue for issue in value.get('issues',[])):
                result['issue_errors'].append(name+': missing explanation for '+field)
        if oracle['route']['next_action']=='inspect-message' and not any(issue.lower().startswith('override:') for issue in value.get('issues',[])):
            result['issue_errors'].append(name+': missing override issue')
    return result


def report(records, expected, result):
    configurations = []
    for record in records:
        config = {'response_source':record['response_source'],
                  'settings':record.get('processing_settings',{})}
        if config not in configurations:
            configurations.append(config)
    lines = ['# Accuracy and factual comparison','',
        'These expected facts were transcribed from the messages and office policy in planning/plan.md before the extraction implementation or measured outputs. The independent machine-readable oracle is tests/expected.json; it is never regenerated from extractions. Mock fixtures were authored from this same source review for repeatability, so matching mock replay does not measure live model accuracy.','',
        '## Comparison procedure','',
        'For every expected document, compare all twelve scalar fields: '+', '.join(SCALARS)+'. Use exact decoded string equality (including business-purpose wording) and null equality. Do not lowercase, trim, infer dates or award partial credit. The canonical business-purpose excerpts below are measurement choices; another faithful summary may differ in exact-match score without being a factual error.','',
        f'Denominator: {len(expected)} documents × 12 scalar fields = {result["total"]}. A missing/error extraction contributes zero of twelve, even where expected values are null. Absent fields also fail. Historical attempts and repeated runs do not enlarge or shrink the denominator. Duplicate current IDs are rejected; unexpected IDs are reported separately. No minimum score is invented.','',
        'Routing triples (status, owner, next_action), schema validity, decoded quote-substring integrity and required missing/override issue coverage are checked separately from scalar exact matches; quote/issue ordering and prose do not receive scalar credit. Conflicting/corrected facts are judged against the source/policy, not against another model output.','',
        '## Recorded observation','',
        f'Scalar exact matches: **{result["matched"]}/{result["total"]}**. Routing matches: **{result["routing_matches"]}/{result["documents"]}**. Schema errors: {len(result["schema_errors"])}; quote errors: {len(result["quote_errors"])}; issue errors: {len(result["issue_errors"])}. Response sources: '+', '.join(sorted({r['response_source'] for r in records}))+'.',
        '', 'No live-provider observation was made for the committed mock deliverables. A clean mock match is a pipeline/comparison regression result, not a live-model accuracy claim. Tests deliberately change a field (251/252), fail a document (240/252), and omit a document without reducing the 252 denominator.','',
        'Factual-error reporting: inspect every differing document/field below, including expected and actual values; distinguish an incorrect/missing fact from a faithful alternative purpose wording in human review. Absence of differences in mock replay is not evidence that a live model never hallucinates.','',
        '```json',json.dumps(result,ensure_ascii=False,indent=2),'```','',
        '## Model and configuration','', '```json',json.dumps(configurations,ensure_ascii=False,indent=2),'```','',
        '## Source-derived expectations','',
        'Every row quotes its complete source message so that all scalar expectations, including absent facts, can be reviewed independently. Policy: materials/office-policy.md §§ Extracted facts and Review queue; missing/unresolved scalars are null, corrections replace earlier values, unlabelled conflicts remain unresolved and relative dates remain null. IT-006 read permission and IT-014 retained reversed dates follow the user decision recorded in planning/plan.md.','',
        '| Document | Expected scalar facts | Expected routing | Exact source quote |',
        '|---|---|---|---|']
    for name,item in expected.items():
        cells = [name,'`'+json.dumps(item['facts'],ensure_ascii=False,sort_keys=True)+'`',
                 '`'+json.dumps(item['route'],sort_keys=True)+'`','“'+item['source_quote']+'”']
        lines.append('| '+' | '.join(cell.replace('|','\\|').replace('\n','<br>') for cell in cells)+' |')
    lines += ['', 'IT-021.json is the authored paraphrase under tests/inputs/, with fresh wording quoted above. The current queue/extractions submission workspace contains only the supplied 20 messages; accuracy uses a separate 21-document temporary workspace.','']
